async function recognize(req, res) {
    const { id } = req.params;
    const { image } = req.body;

    if (!image) return res.status(400).json({ error: 'image is required' });

    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
