    event.preventDefault();
    setError('');
    setStatus('');

    try {
      const payload = { name, email, birthDate };
      if (password) payload.password = password;

      const response = await fetch(API_BASE, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
