      localStorage.setItem('authUser', JSON.stringify({ ...currentUser, ...data, token: authToken }));
      setStatus('Profile updated successfully');
      setPassword('');
    } catch (err) {
      setError('Profile update failed');
    }
  };

  const handleDelete = async () => {
